async function replaceIn({ workspace: { read, edit } }, p: { file: string; pairs: [string, string][] }) {
  const r = await read(p.file, { format: "raw" });
  let c = r.content as string;
  for (const [a, b] of p.pairs) {
    const i = c.indexOf(a);
    if (i < 0) throw new Error(`not found in ${p.file}: ${a.slice(0, 80)}`);
    if (c.indexOf(a, i + 1) >= 0) throw new Error(`ambiguous in ${p.file}: ${a.slice(0, 80)}`);
    c = c.slice(0, i) + b + c.slice(i + a.length);
  }
  return edit(p.file, { revision: r.revision, changes: [{ kind: "replaceFile", content: c }] });
}
